// OrderDetail.jsx
import React, { useEffect, useMemo, useState } from "react";
import { Button, Spinner } from "react-bootstrap";
import "./OrderDetail.css";
import { getMyOrderDetail } from "../../Services/ApiUserService.jsx";
import { useParams } from "react-router-dom";

const fmtDateTime = (iso) => {
    try {
        const d = new Date(iso);
        const date = d.toLocaleDateString("vi-VN", { day: "2-digit", month: "2-digit", year: "numeric" });
        return `${date}`;
    } catch { return "-"; }
};

const fmtMoney = (n) =>
    (Number(n) || 0).toLocaleString("vi-VN", { maximumFractionDigits: 0 }) + " đ";

/** Ưu tiên login_name/username/email làm cột trái; cột phải gộp username|password|phần còn lại */
const parseAccountItem = (item) => {
    if (!item || typeof item !== "object") return { left: "-", right: "-" };


    const u =
        item.login_name ??
        item.username ??
        item.email ??
        item.name ??
        item.account ??
        item.tai_khoan ??
        "Tài khoản";

    const p = item.password ?? item.pass ?? item.pw;

    const rest = Object.entries(item)
        .filter(([k]) => !["login_name", "username", "email", "name", "account", "tai_khoan", "password", "pass", "pw"].includes(k))
        .map(([k, v]) => `${k}:${typeof v === "object" ? JSON.stringify(v) : String(v)}`)
        .join(" | ");

    const right = [u, p, rest].filter(Boolean).join(" | ");
    return { left: String(u), right: right || "-" };
};

const joinAllCredentials = (items) =>
    items.map(parseAccountItem).map(({ left, right }) => `${left} -> ${right}`).join("\n");

const OrderDetail = () => {
    const { id } = useParams();
    const [detail, setDetail] = useState(null);
    const [loading, setLoading] = useState(false);
    const [err, setErr] = useState("");

    useEffect(() => {
        (async () => {
            setLoading(true);
            setErr("");
            try {
                const data = await getMyOrderDetail(id);
                setDetail(data);
            } catch (e) {
                setErr("Không tải được chi tiết đơn hàng.");
            } finally {
                setLoading(false);
            }
        })();
    }, [id]);

    const rows = useMemo(() => detail?.accounts_info ?? [], [detail]);
    const copyAllText = useMemo(() => joinAllCredentials(rows), [rows]);

    const handleCopyAll = async () => {
        try {
            await navigator.clipboard.writeText(copyAllText);
            alert("Đã sao chép toàn bộ!");
        } catch {
            alert("Không thể sao chép. Hãy copy thủ công.");
        }
    };

    const handleCopyOne = async (text) => {
        try {
            await navigator.clipboard.writeText(text);
            alert("Đã sao chép!");
        } catch { }
    };

    if (loading) {
        return (
            <div className="d-flex align-items-center gap-2 p-3">
                <Spinner animation="border" size="sm" />
                <span>Đang tải chi tiết đơn hàng…</span>
            </div>
        );
    }

    if (err) return <div className="alert alert-danger m-3">{err}</div>;
    if (!detail) return null;

    const datePlaced = fmtDateTime(detail.time);

    return (
        <div className="container py-4 order-detail">
            <p className="mb-3">
                Đơn hàng <strong>#{detail.id}</strong> đã được đặt lúc <strong>{datePlaced}</strong>
            </p>

            <h4 className="fw-bold mb-3">Chi tiết đơn hàng</h4>

            <table className="table table-borderless mb-4 small summary-table">
                <tbody>
                    <tr>
                        <td className="text-secondary">Tài khoản</td>
                        <td className="text-end">{`× ${detail.quantity || 0}`}</td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Tổng số phụ:</td>
                        <td className="text-end fw-semibold">{fmtMoney(detail.total_amount)}</td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Tổng cộng:</td>
                        <td className="text-end fw-semibold">{fmtMoney(detail.total_amount)}</td>
                    </tr>
                </tbody>
            </table>

            <div className="d-flex justify-content-center mb-3">
                <Button variant="danger" className="fw-semibold px-4" onClick={handleCopyAll}>
                    Sao chép toàn bộ
                </Button>
            </div>

            <h5 className="fw-bold mb-3">Tài khoản</h5>
            <div className="table-responsive">
                <table className="table table-bordered align-middle">
                    <thead>
                        <tr>
                            <th className="text-secondary small">TÀI KHOẢN</th>
                            <th className="text-secondary small">THÔNG TIN ĐĂNG NHẬP</th>
                            <th style={{ width: 140 }}></th>
                        </tr>
                    </thead>
                    <tbody>
                        {rows.map((raw, idx) => {
                            const { left, right } = parseAccountItem(raw);
                            return (
                                <tr key={idx}>
                                    <td className="fw-semibold">{left}</td>
                                    <td className="text-break">{right}</td>
                                    <td className="text-end">
                                        <Button variant="danger" className="fw-semibold" onClick={() => handleCopyOne(right)}>
                                            SAO CHÉP
                                        </Button>
                                    </td>
                                </tr>
                            );
                        })}
                        {rows.length === 0 && (
                            <tr>
                                <td colSpan={3} className="text-center text-muted">
                                    Không có thông tin tài khoản.
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            <h5 className="fw-bold mt-4 mb-2">Địa chỉ thanh toán</h5>
            <div className="text-muted">N/A</div>
        </div>
    );
};

export default OrderDetail;
